x_938076_backup_0_backup_scripts.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        g_form.setValue('validation_status', 'pending_upload');
        g_form.clearValue('validation_summary');
        return;
    }

    var currentTradeMarket = g_form.getDisplayValue('owning_business');

    // Store the promise from spModal.open()
    var tempModalPromise = null; // Initialize to null for robustness

    // 1. Show the temporary "calculating" widget IMMEDIATELY
    try {
        tempModalPromise = spModal.open({
            title: 'Processing File...',
            widget: 'hsbc_loading_bar_modal', // <--- IMPORTANT: Ensure this is the correct ID for YOUR loading widget
            widgetInput: {
                message: 'Analyzing file for validation. This may take a moment...'
            },
            size: 'sm',
            backdrop: 'static',
            keyboard: false
        });
        console.log('Loading modal opened. tempModalPromise:', tempModalPromise); // DEBUG LINE
    } catch (e) {
        console.error('Error opening loading modal:', e); // DEBUG LINE
        // Fallback if modal can't open
        g_form.addInfoMessage('File processing started...');
    }

    g_form.setValue('validation_status', 'validation_in_progress'); 

    // 2. Make the GlideAjax call
    var checkIfEmptyFile = new GlideAjax('x_hsb11_hsbc_mss_o.MSSCustodyBulkFileUpload');
    checkIfEmptyFile.addParam('sysparm_name', 'checkBulkValidationStatus');
    checkIfEmptyFile.addParam('sysparm_market', currentTradeMarket);
    // Use getXMLAnswer with the callback function
    checkIfEmptyFile.getXMLAnswer(checkifemptyRec);

    function checkifemptyRec(response) {
        console.log('GlideAjax callback received response:', response); // DEBUG LINE

        // 3. Attempt to close the temporary loading widget
        // Use typeof check for robustness, as discussed
        if (tempModalPromise && typeof tempModalPromise.close === 'function') { 
            console.log('Attempting to close loading modal via tempModalPromise.close()'); // DEBUG LINE
            try {
                tempModalPromise.close();
                console.log('Loading modal successfully closed.'); // DEBUG LINE
            } catch (e) {
                console.error('Error closing loading modal:', e); // DEBUG LINE
            }
        } else {
            console.warn('Could not close loading modal. tempModalPromise:', tempModalPromise, 'tempModalPromise.close:', tempModalPromise ? typeof tempModalPromise.close : 'N/A'); // CRITICAL DEBUG LINE
            // This warning is crucial if the modal isn't closing.
            // If the modal persists, you might need a fallback, e.g., refreshing the page (not ideal).
        }

        var dataSummary = '';
        var errorDetails = response.split("/");
        var result = errorDetails[0];
        var summaryTotalCount = errorDetails[1] ? errorDetails[1] : 'NA';
        var summaryErrorRecords = errorDetails[2] ? errorDetails[2] : 'NA';
        var summaryValidRecords = errorDetails[3] ? errorDetails[3] : 'NA';

        try {
            // YOUR EXISTING LOGIC STARTS HERE
            if ((response.includes("Invalid file type")) || (response.includes("File size exceeded"))) {
                g_form.addErrorMessage(result);
                g_form.setValue('validation_status', 'validation_failed');

                if (response.includes("Invalid file type")) {
                    dataSummary = 'Validation failed. The file uploaded should be of type .xlsx';
                } else if (response.includes("File size exceeded")) {
                    dataSummary = 'Validation failed. The file uploaded exceeds allowed limit of 10MB';
                } else {
                    dataSummary = 'Validation failed. The file uploaded seems to be corrupted. Please review';
                }
            } else if (result == "Validation Failed" || result == "No Errors" || result == "Validation Successful") {
                // 4. Open the main error details widget
                spModal.open({
                    title: 'Validation Errors',
                    widget: 'bulk_file_upload_error_details', // Your main widget's sys_id or ID
                    widgetInput: {
                        tradeMarket: currentTradeMarket
                    },
                    size: 'lg'
                }).then(function(modalResult) { // Use a different variable name for modal close result
                    // Handle modal close if needed
                    console.log('Main error modal closed, result:', modalResult); // DEBUG LINE
                });

                if (result == "No Errors" || result == "Validation Successful") {
                    dataSummary = 'Validation successful. The data uploaded contains less than 10% of error records';
                    g_form.setValue('validation_status', 'validation_successful');
                } else if (result == "Validation Failed") {
                    dataSummary = 'Validation Failed. The data uploaded contains more than 10% of error records';
                    g_form.setValue('validation_status', 'validation_failed');
                } else {
                    dataSummary = 'Validation Failed. The data uploaded contains more than 10% of error records';
                    g_form.setValue('validation_status', 'validation_failed');
                }

            } else if (result == "No records Found") {
                dataSummary = 'Validation failed. The file uploaded seems to be empty. Please review';

                spModal.open({
                    title: 'Empty File Alert!',
                    widget: 'bulk_file_upload_empty_alert', // Your widget for empty file alert
                    size: 'lg'
                }).then(function(modalResult) {
                    console.log('Empty file alert modal closed, result:', modalResult); // DEBUG LINE
                });

                g_form.setValue('validation_status', 'validation_failed');

            } else {
                dataSummary = 'Validation failed. The file uploaded seems to be corrupted. Please review';
                g_form.setValue('validation_status', 'validation_failed');
            }

            // Validation Summary HTML update
            var htmlContent = '<p style="color: black;">Total Records : <strong>' + summaryTotalCount + '</strong></p>' +
                '<p style="color: black;">Error Records : <strong style="color: red;">' + summaryErrorRecords + '</strong></p>' +
                '<p style="color: black;">Valid Records : <strong style="color: green;">' + summaryValidRecords + '</strong></p>' +
                '<p style="color: black;">Note:&nbsp;' + dataSummary + '</p>';

            g_form.setValue('validation_summary', htmlContent);

        } catch (ex) {
            g_form.addErrorMessage('Error within checkifemptyRec callback: ' + ex); // DEBUG LINE
            console.error('Error in checkifemptyRec:', ex); // CRITICAL DEBUG LINE
        }
    }
}
